CREATE TABLE `User` (`id` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `email` VARCHAR(191) NOT NULL, `passwordHash` VARCHAR(191) NOT NULL, `phone` VARCHAR(191) NULL, `role` ENUM('CUSTOMER','ADMIN') NOT NULL DEFAULT 'CUSTOMER', `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `User_email_key`(`email`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Destination` (`id` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `description` TEXT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `Destination_name_key`(`name`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `TravelPackage` (`id` VARCHAR(191) NOT NULL, `slug` VARCHAR(191) NOT NULL, `title` VARCHAR(191) NOT NULL, `category` VARCHAR(191) NOT NULL, `description` TEXT NOT NULL, `price` INTEGER NOT NULL, `depositPercent` INTEGER NOT NULL DEFAULT 30, `image` VARCHAR(191) NOT NULL, `destinationId` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `TravelPackage_slug_key`(`slug`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Schedule` (`id` VARCHAR(191) NOT NULL, `packageId` VARCHAR(191) NOT NULL, `departureDate` DATETIME(3) NOT NULL, `capacity` INTEGER NOT NULL, `meetingPoint` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `Schedule_packageId_departureDate_key`(`packageId`,`departureDate`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ItineraryDay` (`id` VARCHAR(191) NOT NULL, `packageId` VARCHAR(191) NOT NULL, `day` INTEGER NOT NULL, `detail` TEXT NOT NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Facility` (`id` VARCHAR(191) NOT NULL, `packageId` VARCHAR(191) NOT NULL, `detail` VARCHAR(191) NOT NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Booking` (`id` VARCHAR(191) NOT NULL, `bookingNumber` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `packageId` VARCHAR(191) NOT NULL, `scheduleId` VARCHAR(191) NOT NULL, `participantQty` INTEGER NOT NULL, `totalAmount` INTEGER NOT NULL, `depositAmount` INTEGER NOT NULL, `remainingAmount` INTEGER NOT NULL, `status` ENUM('WAITING_DEPOSIT','SIMULATED_DEPOSIT_RECORDED','CONFIRMED','COMPLETED','CANCELLED') NOT NULL DEFAULT 'WAITING_DEPOSIT', `paymentStatus` ENUM('NOT_SIMULATED','SIMULATED_DEPOSIT','SIMULATED_PAID','CANCELLED') NOT NULL DEFAULT 'NOT_SIMULATED', `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `Booking_bookingNumber_key`(`bookingNumber`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Participant` (`id` VARCHAR(191) NOT NULL, `bookingId` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `phone` VARCHAR(191) NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `SimulatedPayment` (`id` VARCHAR(191) NOT NULL, `bookingId` VARCHAR(191) NOT NULL, `amount` INTEGER NOT NULL, `status` ENUM('NOT_SIMULATED','SIMULATED_DEPOSIT','SIMULATED_PAID','CANCELLED') NOT NULL DEFAULT 'SIMULATED_DEPOSIT', `simulatedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `SimulatedPayment_bookingId_key`(`bookingId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `GalleryImage` (`id` VARCHAR(191) NOT NULL, `title` VARCHAR(191) NOT NULL, `destination` VARCHAR(191) NOT NULL, `imageUrl` VARCHAR(191) NOT NULL, `altText` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Promotion` (`id` VARCHAR(191) NOT NULL, `title` VARCHAR(191) NOT NULL, `description` TEXT NOT NULL, `code` VARCHAR(191) NULL, `validUntil` DATETIME(3) NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CustomItineraryRequest` (`id` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `phone` VARCHAR(191) NOT NULL, `destination` VARCHAR(191) NOT NULL, `travelDates` VARCHAR(191) NOT NULL, `participants` INTEGER NOT NULL, `notes` TEXT NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `TravelPackage` ADD CONSTRAINT `TravelPackage_destinationId_fkey` FOREIGN KEY (`destinationId`) REFERENCES `Destination`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Schedule` ADD CONSTRAINT `Schedule_packageId_fkey` FOREIGN KEY (`packageId`) REFERENCES `TravelPackage`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `ItineraryDay` ADD CONSTRAINT `ItineraryDay_packageId_fkey` FOREIGN KEY (`packageId`) REFERENCES `TravelPackage`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Facility` ADD CONSTRAINT `Facility_packageId_fkey` FOREIGN KEY (`packageId`) REFERENCES `TravelPackage`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Booking` ADD CONSTRAINT `Booking_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Booking` ADD CONSTRAINT `Booking_packageId_fkey` FOREIGN KEY (`packageId`) REFERENCES `TravelPackage`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Booking` ADD CONSTRAINT `Booking_scheduleId_fkey` FOREIGN KEY (`scheduleId`) REFERENCES `Schedule`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Participant` ADD CONSTRAINT `Participant_bookingId_fkey` FOREIGN KEY (`bookingId`) REFERENCES `Booking`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `SimulatedPayment` ADD CONSTRAINT `SimulatedPayment_bookingId_fkey` FOREIGN KEY (`bookingId`) REFERENCES `Booking`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
